  rows.push({
    orgId,
    recipientId,
    kind,
    title: payload.title,
    body: payload.body,
    href: payload.href,
    actorId: payload.actorId,
    projectId: payload.projectId ?? null,
    channels,
  });
}

  return preferenceRepo.upsertPreference(input);
}

/**
 * Guards a mute the same way reading the project is guarded: the org must be
 * the actor's, the project must exist in it, and the actor needs `project:read`.
 */
async function assertCanReadProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
}

/** Silences one project for the actor alone. Repeating it changes nothing. */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.muteProject(orgId, actor.userId, projectId);
}

/** Lifts the actor's mute of one project. A missing mute is a no-op. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.unmuteProject(orgId, actor.userId, projectId);
}

/** Projects the actor has muted inside this organization. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return muteRepo.listMutedProjectIds(orgId, actor.userId);
}

